def need(ok, message):
    if not ok:
        raise ValueError(message)


def load(name):
    need(name in DEPENDENCIES and type(DEPENDENCIES[name])is str and len(DEPENDENCIES[name])==64,
         'Helper source contract is not frozen')
    path = HERE / name
    need(hashlib.sha256(path.read_bytes()).hexdigest() == DEPENDENCIES[name], 'Frozen portable helper changed')
    spec = importlib.util.spec_from_file_location('_portable_' + name.replace('.', '_'), path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def model_stage(reader, epoch, specs):
    need(epoch in ('baseline-v1', 'protected-v6-four-lane-coordinate', 'encrypted-v5-coordinate', 'protected-v7-projection-fourway', 'protected-v8-sha-direct-add', 'protected-v9-dense-sha','protected-v15-compact-prefix'),
         'Unreviewed source/model epoch; no results inherited')
    helper = load('current_greedy_models_portable_v15_v1.py')
    complete = reader.role('model_complete')
    if epoch=='protected-v15-compact-prefix':
        need(reader.variant=='kv-protected','V15 model variant differs')
        return helper.validate_protected_v15_models(reader,complete,specs)
    if epoch == 'baseline-v1':
        need(reader.variant == 'baseline', 'Source/model variant differs')
        return helper.validate_greedy_models('baseline', reader, complete, specs)
    if epoch == 'protected-v6-four-lane-coordinate':
        need(reader.variant == 'kv-protected', 'Source/model variant differs')
        # A successful V6 finite model is not an eligible V6 image and must not
        # be relabelled as the forthcoming projection-source V7 epoch.
        return helper.validate_greedy_models('kv-protected', reader, complete, specs)
    if epoch == 'protected-v9-dense-sha':
        need(reader.variant == 'kv-protected', 'Source/model variant differs')
        return helper.validate_protected_v9_models(reader, complete, specs)
    if epoch == 'protected-v8-sha-direct-add':
        need(reader.variant == 'kv-protected', 'Source/model variant differs')
        return helper.validate_protected_v8_models(reader, complete, specs)
    if epoch == 'protected-v7-projection-fourway':
        need(reader.variant == 'kv-protected', 'Source/model variant differs')
        return helper.validate_protected_v7_models(reader, complete, specs)
    if epoch == 'encrypted-v5-coordinate':
        need(reader.variant == 'encrypted-memory', 'Source/model variant differs')
        return helper.validate_encrypted_models(reader, complete, specs)
    raise ValueError('Unreviewed source/model epoch; no results inherited')



def source_proof_stage(reader, epoch, specs, native_inputs=None):
    proof = load('current_greedy_proofs_portable_v3.py')
    if epoch=='protected-v15-compact-prefix':
        if native_inputs is None:
            base=reader.json(specs['source_input_plan']['path'],specs['source_input_plan'])
            need(specs['source_input_plan']['sha256']=='7f78feaa4a3a9419bd7d3023b2f8cace2a6829a578362d347eff24d79b8d0684',
                 'Exact V15 base-source proof context required')
            native_inputs=base['inputs']
        bridge=load('current_greedy_v15_proof_portable_v1.py')
        return bridge.validate_v15_proofs(reader,reader.role('source_scoped_proofs'),specs,native_inputs,query_recheck=proof.check_queries)
    if epoch == 'encrypted-v5-coordinate':
        need(native_inputs is not None, 'Actual selected CFC native source graph required')
        bridge = load('current_greedy_encrypted_v5_proof_portable_v1.py')
        return bridge.validate_encrypted_v5_attention_bridge(reader,
            reader.role('source_scoped_proofs'), specs, native_inputs,
            query_recheck=proof.check_queries)
    if epoch not in ('protected-v7-projection-fourway', 'protected-v8-sha-direct-add', 'protected-v9-dense-sha'):
        need(native_inputs is not None, 'Actual closed native source graph required for this proof stage')
        return proof.validate_attention_proof(reader, reader.role('source_scoped_proofs'), specs, native_inputs)
    if native_inputs is None:
        # Source-only association is independent of failed/incomplete routing.
        # This input plan is not a completed native image or an eligible policy.
        source = reader.role('source_candidate')
        helper = load('current_greedy_native_portable_v15_v1.py')
        expected = helper.EPOCHS[epoch]
        need(reader.pin(reader.data['roles']['source_candidate'])['sha256'] == expected['candidate_sha256'], 'Exact protected source candidate epoch required')
        plan = reader.json(specs['source_input_plan']['path'], specs['source_input_plan'])
        need(plan['variant'] == 'kv-protected' and plan['candidate_receipt'] == reader.pin(reader.data['roles']['source_candidate']), 'Source input plan/candidate differs')
        if epoch == 'protected-v9-dense-sha':
            plan_origin = specs['source_input_plan']['path']
            need(plan_origin in helper.V9_NATIVE_PLANS
                 and helper.pin2(specs['source_input_plan']) == helper.V9_NATIVE_PLANS[plan_origin],
                 'Exact reviewed V9 R1 source-input plan required')
        if epoch == 'protected-v8-sha-direct-add':
            plan_origin = specs['source_input_plan']['path']
            need(plan_origin in helper.V8_NATIVE_PLANS
                 and helper.pin2(specs['source_input_plan']) == helper.V8_NATIVE_PLANS[plan_origin],
                 'Exact reviewed V8 source-input plan required')
        helper.candidate_input_inventory(reader, source, plan, expected)
        native_inputs = plan['inputs']
    if epoch == 'protected-v9-dense-sha':
        bridge = load('current_greedy_v9_proof_bridge_portable_v1.py')
        result = bridge.validate_v9_attention_bridge(reader, reader.role('source_scoped_proofs'), specs,
            native_inputs, proof_recheck=proof.validate_attention_proof)
    elif epoch == 'protected-v8-sha-direct-add':
        bridge = load('current_greedy_v8_proof_bridge_portable_v1.py')
        result = bridge.validate_v8_attention_bridge(reader, reader.role('source_scoped_proofs'), specs,
            native_inputs, proof_recheck=proof.validate_attention_proof)
    else:
        bridge = load('current_greedy_v7_proof_bridge_portable_v1.py')
        result = bridge.validate_v7_attention_bridge(reader, reader.role('source_scoped_proofs'), specs,
            native_inputs, proof_recheck=proof.validate_attention_proof)
    need(result['additional_assertions_or_queries_claimed'] == 0 and result['native_or_board_authority'] is False,
         'Source-only attention bridge cannot qualify a native image')
    return result

def protected_captured_physical_context(reader,plan,finished,specs):
    """Authenticate the R5 metadata exception explicitly, separate from raw replay."""
    reference=load('current_greedy_shared_host_portable_v15_v3.py').CAPTURED_MANIFEST_REFERENCE
    need(reader.variant=='kv-protected'
         and plan['captured_manifest_reference']==finished['captured_manifest_reference']==reference
         and reference['logical_manifest_path']not in plan['source_inputs'],
         'Protected physical PLAN/FIN must bind the exact immutable metadata reference')
    for key in('physical_manifest','reference_ledger','reference_basis_manifest','helper'):
        row=reference[key]
        need(plan['source_inputs'].get(row['path'])=={k:row[k]for k in('bytes','sha256')},
             'Protected physical source ledger omits an actual reference/helper pin')
        reader.read(row['path'],row)
    need(plan['source_inputs'].get(PROTECTED_R5_RUNNER_PIN['path'])==
         {k:PROTECTED_R5_RUNNER_PIN[k]for k in('bytes','sha256')},
         'Exact R5 runner source must be pinned by the actual physical PLAN')
    reader.read(PROTECTED_R5_RUNNER_PIN['path'],PROTECTED_R5_RUNNER_PIN)
    need(type(FINAL_PROTECTED_PHYSICAL_REVIEW_PIN)is dict
         and specs['independent_review']==FINAL_PROTECTED_PHYSICAL_REVIEW_PIN
         and specs['reviewer_source']==PROTECTED_R4_REVIEWER_PIN,
         'Actual closed protected review and exact R4 reviewer source contract pending')
    reader.read(PROTECTED_R4_REVIEWER_PIN['path'],PROTECTED_R4_REVIEWER_PIN)
    row=FINAL_PROTECTED_PHYSICAL_REVIEW_PIN;review=reader.json(row['path'],row)
    need(review['schema']=='greedy-physical-campaign-independent-raw-review-v15-mixed'
         and review['variant']=='kv-protected'and review['checker']==PROTECTED_R4_REVIEWER_PIN
         and review['actual_finished']==reader.pin(reader.data['roles']['physical_campaign'])
         and review['policy']==reader.pin(reader.data['roles']['root_policy'])
         and review['physical_plan']==finished['plan']and review['image']==finished['image']
         and review['actual_raw_log_or_closed_prefix']==finished['raw_uart']
         and review['captured_manifest_reference']==reference
         and review['passed']is review['complete_campaign']is review['closed_cases_passed']is True
         and review['source_inputs_unchanged']is review['all_consumed_raw_bytes_and_case_results_replayed']is True
         and review['case_count']==10 and review['main_reference_outputs']==395 and review['settings_commands']==0,
         'Protected R5 campaign/R4 review/raw/plan/policy/image/reference identities differ')
    need(all(review[name]is False for name in('hardware_access','browser_or_server_access',
        'owner_or_programmer_probes','release_qualified')),'Protected raw-review scope overclaim')
    return dict(captured_manifest_reference=reference,actual_R5_runner_source_rehashed=True,
        actual_R4_review_source_and_record_rehashed=True,reference_view_was_metadata_only=True)


def physical_stage(reader, epoch, specs, native):
    helper = load('current_greedy_uart_portable_v1.py')
    role = reader.data['roles']['physical_campaign']
    finished_bytes = reader.read(role)
    finished = reader.json(role)
    plan_bytes = reader.read(specs['plan'], finished['plan'])
    plan = reader.json(specs['plan'])
    policy_origin = reader.data['roles']['root_policy']
    policy = reader.role('root_policy')
    need(plan['policy'] == reader.pin(policy_origin) and policy['image'] == plan['image']
         and policy['source_candidate'] == plan['source_candidate']
         and plan['source_candidate'] == reader.pin(reader.data['roles']['source_candidate']),
         'Physical original policy/image/source differs from selected closed graph')
    guard = reader.read(specs['guard'])
    registry = load('current_greedy_native_portable_v15_v1.py').EPOCHS
    need(epoch in registry and hashlib.sha256(guard).hexdigest() == registry[epoch]['guard_sha256'],
         'Actual physical loader epoch differs')
    if epoch=='protected-v15-compact-prefix':
        load('current_greedy_v15_scope_portable_v1.py').root_guard_identity(
            reader,specs['guard'],registry[epoch]['guard_sha256'])
        protected_captured_physical_context(reader,plan,finished,specs)
    omitted = reader.data['specifications']['native']['licensed_inputs']
    recovery_omissions={}
    for origin, wanted in plan['source_inputs'].items():
        if origin in DECLARED_RECOVERY_PROVENANCE_OMISSIONS:
            need(wanted==DECLARED_RECOVERY_PROVENANCE_OMISSIONS[origin],
                 'Private operator recovery provenance differs from exact bounded source contract')
            recovery_omissions[origin]=wanted
        elif origin in DECLARED_OPERATOR_TOOL_PROVENANCE_OMISSIONS:
            need(wanted == DECLARED_OPERATOR_TOOL_PROVENANCE_OMISSIONS[origin],
                 'Exact recorded operator-tool provenance differs')
        elif origin in omitted:
            need(omitted[origin] == wanted, 'Declared licensed source identity differs')
        else:
            reader.read(origin, wanted)
    for name in ('load', 'flash_lineage'):
        reader.read(plan[name]['path'], plan[name])
    loaded = reader.json(plan['load']['path'])
    need(loaded['passed'] is True and loaded['image_sha256'] == native['image']['sha256']
         and loaded['sram_load_reported'] is True and loaded['flash_modified'] is False
         and loaded['configuration_independently_attested'] is False,
         'Actual SRAM load record/image/scope differs')
    raw_uart = reader.read(specs['raw_uart'], finished['raw_uart'])
    result = helper.validate_campaign(finished_bytes=finished_bytes, plan_bytes=plan_bytes,
        raw_uart_bytes=raw_uart, frozen_plan_bytes=reader.read(specs['frozen_plan']),
        goldens={name: reader.read(origin) for name, origin in specs['goldens'].items()},
        variant=reader.variant, image_sha256=native['image']['sha256'])
    need(set(specs['case_files']) == {row['name'] for row in result['cases']}, 'All actual closed per-case receipts required')
    for row in result['cases']:
        need(reader.json(specs['case_files'][row['name']]) == row, 'Closed per-case receipt differs from actual raw replay')
    if epoch=='protected-v15-compact-prefix':
        need(recovery_omissions==DECLARED_RECOVERY_PROVENANCE_OMISSIONS,
             'Actual R5 operator-backup provenance must remain complete as digest metadata')
    result['declared_private_recovery_provenance_omissions']=recovery_omissions
    result['declared_operator_tool_provenance_omissions'] = {origin: wanted for origin, wanted in plan['source_inputs'].items() if origin in DECLARED_OPERATOR_TOOL_PROVENANCE_OMISSIONS}
    result['operator_tool_payload_bytes_redistributed_or_rehashed'] = False
    result['private_recovery_payload_bytes_redistributed_or_rehashed']=False
    result['operator_backup_content_independently_replayed']=False
    return result


def tokenizer_factory(raw):
    # Only browser-stage checking needs the existing host environment. The
    # supplied tokenizer object is built from exact bytes checked by the helper.
    import importlib.metadata
    need(importlib.metadata.version('tokenizers') == '0.23.2', 'Use the existing tokenizers0.23.2 host environment')
    from tokenizers import Tokenizer
    return Tokenizer.from_str(raw.decode())


def require_public_capsule_without_factory_payloads(reader):
    """Reject private recovery bytes under every provenance alias/object binding."""
    tool_digests = {row['sha256'] for row in DECLARED_OPERATOR_TOOL_PROVENANCE_OMISSIONS.values()}
    need(all(row['original']['sha256'] not in tool_digests for row in reader.bindings.values()),
         'Operator tools are exact metadata-only provenance, not public capsule payloads')
    need(all(row['original']['sha256']not in FORBIDDEN_FACTORY_RECOVERY_RAW_SHA256
             for row in reader.bindings.values()),
         'Factory recovery BIN/JSONL payloads are metadata-only and cannot be public capsule objects')


def inspect(package, capsule_pin, epoch, stage):
    capsules = load('current_greedy_capsules_v2.py')
    reader = capsules.Capsule(package, capsule_pin)
    require_public_capsule_without_factory_payloads(reader)
    specs = reader.data['specifications']
    need(stage in ('model', 'source-proof', 'native', 'proof', 'census', 'physical', 'browser'), 'Explicit scoped replay stage required')
    if epoch == 'protected-v8-sha-direct-add':
        need(stage in ('model', 'native', 'source-proof', 'proof'), 'V8 physical/browser/census callbacks remain unconfigured')
    if epoch == 'protected-v9-dense-sha':
        need(stage in ('model', 'native', 'source-proof', 'proof'), 'V9 physical/browser/census callbacks remain unconfigured')
    result = dict(schema='current-greedy-portable-scoped-recheck-v8', variant=reader.variant, epoch=epoch,
                  stage=stage, release_qualified=False, historical_354_or_seeded_qualification_relabelled=False,
                  hardware_or_server_access=False, solver_model_native_or_OpenSSL_executed=False)
    if stage == 'model':
        result['model'] = model_stage(reader, epoch, specs['model'])
    elif stage == 'source-proof':
        need(epoch in ('protected-v7-projection-fourway', 'protected-v8-sha-direct-add', 'protected-v9-dense-sha','protected-v15-compact-prefix'), 'Source-only proof stage requires an explicit protected bridge epoch')
        result['source_scoped_proof'] = source_proof_stage(reader, epoch, specs['proof'])
        result['native_completed_image_association_performed'] = False
    else:
        native_helper = load('current_greedy_native_portable_v15_v1.py')
        native = native_helper.validate_native_graph(reader, epoch, specs['native'])
        result['native'] = native
        if stage != 'native':
            result['model'] = model_stage(reader, epoch, specs['model'])
        if stage == 'census':
            census = load('current_greedy_census_portable_v15_v1.py')
            result['recorded_census'] = census.validate_census(reader, reader.data['roles']['mapped_multiplier_census'], epoch, native)
        if stage == 'proof':
            result['source_scoped_proof'] = source_proof_stage(reader, epoch, specs['proof'], reader.role('native_plan')['inputs'])
        if stage in ('physical', 'browser'):
            result['physical'] = physical_stage(reader, epoch, specs['physical'], native)
        if stage == 'browser':
            browser = load('current_greedy_browser_portable_v15_v3.py')
            result['browser'] = browser.validate_campaign(prepared_pin=specs['browser']['prepared'],
                completed_pin=reader.pin(reader.data['roles']['browser_campaign']), cli_uart_replay=result['physical'],
                read_origin=reader.read, tokenizer_factory=tokenizer_factory, variant=reader.variant,
                image_sha256=native['image']['sha256'])
    reader.unchanged()
    result['consumed_original_origins'] = len(reader.consumed)
    result['passed_scoped_recheck'] = True
    return result


def check_current(package,index_pin):
    """Admit only one source-frozen allthree/current+history/host contract.

    The index and capsule data cannot configure this contract or supply trusted
    PASS maps. Every stage is called here and its results are passed directly
    to the shared-host callback. The source contract pins all declared members
    except this running entrypoint, whose manifest identity is derived at run
    time to avoid a self/MANIFEST/index hash cycle.
    """
    contract=REVIEWED_RELEASE_CONTRACT
    need(type(contract)is dict and contract.get('schema')=='greedy-final-reviewed-release-contract-v15-v1',
        'Current release pending: actual reviewed three-design/host/history contract is not frozen')
    capsules=load('current_greedy_capsules_v2.py')
    need(type(contract['variants'])is dict and set(contract['variants'])==VARIANTS,
        'Exactlythree explicit selected variants required')
    epochs={'baseline':'baseline-v1','kv-protected':'protected-v15-compact-prefix','encrypted-memory':'encrypted-v5-coordinate'}
    need(contract['entrypoint']=={'path':'tools/check_current_three_greedy_v15_v4.py'}
        and contract['manifest_path']=='MANIFEST.json','Exact reviewed entrypoint/manifest layout required')
    need(index_pin==contract['index'],'Actual final index differs from source-frozen identity')
    def package_bytes(row):
        path=capsules.member(package,row['path']);wanted={k:row[k]for k in('bytes','sha256')}
        need(capsules.identity(path)==wanted,'Final package member differs: '+row['path'])
        raw=path.read_bytes();need(capsules.raw_identity(raw)==wanted,'Final package member changed during read')
        return raw
    index=capsules.decode(package_bytes(index_pin))
    expected_index=dict(schema='greedy-final-current-release-index-v15-v1',
        variants={v:dict(epoch=contract['variants'][v]['epoch'],capsule=contract['variants'][v]['capsule'])for v in sorted(VARIANTS)},
        shared_host=contract['shared_host'],historical_context=contract['historical_context'],role_ledger=contract['role_ledger'])
    need(index==expected_index,'Final index differs from reviewed exact allthree/current/history/source graph')
    readers={};native_results={};model_results={};proof_results={};census_results={};physical_results={};browser_results={};ledger={}
    native_helper=load('current_greedy_native_portable_v15_v1.py')
    census_helper=load('current_greedy_census_portable_v15_v1.py')
    browser_helper=load('current_greedy_browser_portable_v15_v3.py')
    for variant in sorted(VARIANTS):
        selected=contract['variants'][variant]
        need(selected['epoch']==epochs[variant],'Final source epoch differs from reviewed current designs')
        reader=capsules.Capsule(package,selected['capsule']);readers[variant]=reader
        require_public_capsule_without_factory_payloads(reader)
        need(not any(Path(origin).name=='check_current_three_greedy_v15_v4.py'for origin in reader.bindings),
             'Final entrypoint must remain outside capsules that its source contract pins')
        required=set(ROLES)|({'mapped_mutable_ram'}if variant=='kv-protected'else set())
        need(reader.variant==variant and set(reader.data['roles'])==required
            and set(selected['roles'])==required,'Complete exact variant role ledger required')
        ledger[variant]={role:reader.pin(reader.data['roles'][role])for role in sorted(required)}
        need(ledger[variant]==selected['roles'],'Actual role identities differ from reviewed current selection')
        for role in required:reader.role(role)
        specs=reader.data['specifications'];epoch=selected['epoch']
        native_results[variant]=native_helper.validate_native_graph(reader,epoch,specs['native'])
        model_results[variant]=model_stage(reader,epoch,specs['model'])
        proof_results[variant]=source_proof_stage(reader,epoch,specs['proof'],reader.role('native_plan')['inputs'])
        census_results[variant]=census_helper.validate_census(reader,reader.data['roles']['mapped_multiplier_census'],epoch,native_results[variant])
        physical_results[variant]=physical_stage(reader,epoch,specs['physical'],native_results[variant])
        browser_results[variant]=browser_helper.validate_campaign(prepared_pin=specs['browser']['prepared'],
            completed_pin=reader.pin(reader.data['roles']['browser_campaign']),cli_uart_replay=physical_results[variant],
            read_origin=reader.read,tokenizer_factory=tokenizer_factory,variant=variant,
            image_sha256=native_results[variant]['image']['sha256'])
        if variant=='kv-protected':
            need(reader.pin(reader.data['roles']['mapped_mutable_ram'])==reader.role('root_policy')['mapped_mutable_ram'],
                'Mutable RAM role differs from exact selected policy obligation')
        reader.unchanged()
    actual_ledger=capsules.decode(package_bytes(contract['role_ledger']))
    need(actual_ledger==dict(schema='greedy-final-actual-role-ledger-v15-v1',variants=ledger),
        'Final ledger does not exactly name all actual current roles')
    host_row=contract['shared_host'];host_reader=capsules.Capsule(package,host_row['capsule'])
    require_public_capsule_without_factory_payloads(host_reader)
    need(host_reader.variant=='shared-host','Explicit shared-host capsule required')
    host_spec=host_reader.json(host_row['specification']['path'],host_row['specification'])
    host_result=load('current_greedy_shared_host_portable_v15_v3.py').validate_shared_host(
        host_reader=host_reader,variant_readers=readers,native_results=native_results,
        physical_results=physical_results,browser_results=browser_results,spec=host_spec)
    need(host_result['passed']is True and host_result['host79']['total']==79
        and host_result['required_critical_common_source_count']==12
        and host_result['shared_prepared_materialization_context_joined']is True,
        'Allthree fresh browsers must join one actual125-source/79-test common host')
    history_row=contract['historical_context'];history_reader=capsules.Capsule(package,history_row['capsule'])
    require_public_capsule_without_factory_payloads(history_reader)
    need(history_reader.variant=='source-reference','Explicit minimal source-reference capsule required')
    history_spec=history_reader.json(history_row['specification']['path'],history_row['specification'])
    history_result=load('current_greedy_history_portable_v15_v1.py').validate_context(
        history_reader,history_spec,current_native_results=native_results)
    need(history_result['passed']is True and history_result['reference_fixture_only']is True
        and history_result['historical_runnable_release_required']is False,
        'Authenticated minimal source-reference and unchanged current seeded bridge required')
    # The complete declared byte contract excludes only this source file.
    manifest_path=capsules.member(package,contract['manifest_path'])
    before=capsules.identity(manifest_path);manifest=capsules.decode(manifest_path.read_bytes())
    self_name=contract['entrypoint']['path'];self_path=capsules.member(package,self_name)
    need(self_path.samefile(Path(__file__).resolve()),'Current checking entrypoint is outside selected package')
    wanted=dict(contract['file_contract'])
    need(all(row['sha256']not in FORBIDDEN_FACTORY_RECOVERY_RAW_SHA256
             and not any(digest in Path(name).name for digest in FORBIDDEN_FACTORY_RECOVERY_RAW_SHA256)
             for name,row in wanted.items()),
         'Final declared members cannot include factory payloads or their content-addressed archive objects')
    need(self_name not in wanted and 'MANIFEST.json'not in wanted,'Self/MANIFEST hash cycle forbidden')
    wanted[self_name]=capsules.identity(self_path)
    need(type(manifest['files'])is dict and manifest['files']==wanted,
        'Final manifest does not equal complete reviewed member contract plus actual entrypoint')
    for name,row in manifest['files'].items():
        need(capsules.identity(capsules.member(package,name))==row,'Declared final member bytes changed: '+name)
    need(capsules.identity(manifest_path)==before,'Final manifest changed during full byte replay')
    for reader in [*readers.values(),host_reader,history_reader]:reader.unchanged()
    return dict(schema='greedy-final-current-release-byte-admission-v15-v1',passed=True,current_admission=True,
        variant_epochs=epochs,native=native_results,models=model_results,source_proofs=proof_results,
        observational_censuses=census_results,physical=physical_results,browser=browser_results,
        shared_host=host_result,historical_context=history_result,declared_members_rehashed=len(wanted),
        manifest=dict(path=contract['manifest_path'],**before),all_actual_roles_cross_bound=True,
        historical_and_current_namespaces_distinct=True,solver_model_native_or_hardware_executed=False,
        website_or_repository_publication_performed=False,complete_timing_or_whole_machine_theorem=False)


def main():
    need(sys.version_info>=(3,11),'Python3.11 or newer required')
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--package',required=True,type=Path)
    parser.add_argument('--capsule',type=Path);parser.add_argument('--index',type=Path)
    parser.add_argument('--epoch');parser.add_argument('--stage',choices=('model','source-proof','native','proof','census','physical','browser','current'),default='current')
    args=parser.parse_args();capsules=load('current_greedy_capsules_v2.py')
    if args.stage=='current':
        need(args.index is not None and args.capsule is None and args.epoch is None,'Current mode requires only the exact final index')
        row=dict(path=str(args.index),**capsules.identity(capsules.member(args.package,str(args.index))))
        result=check_current(args.package,row)
    else:
        need(args.capsule is not None and args.epoch is not None and args.index is None,'Scoped mode requires capsule and explicit epoch')
        row=dict(path=str(args.capsule),**capsules.identity(capsules.member(args.package,str(args.capsule))))
        result=inspect(args.package,row,args.epoch,args.stage)
    print(json.dumps(result,sort_keys=True))


if __name__=='__main__':main()
